# Let me write a program to test multiple hypotheses

test_input = [[3, 0, 0], [3, 3, 3], [0, 0, 3]]

def hypo1(grid):
    """Hypothesis: 0 where input is non-zero, 2 elsewhere"""
    result = []
    for row in grid:
        new_row = []
        for val in row:
            if val != 0:
                new_row.append(0)
            else:
                new_row.append(2)
        result.append(new_row)
    return result

def hypo2(grid):
    """Hypothesis: 0 on main diagonal, 2 elsewhere"""
    result = []
    for r in range(len(grid)):
        new_row = []
        for c in range(len(grid[r])):
            if r == c:
                new_row.append(0)
            else:
                new_row.append(2)
        result.append(new_row)
    return result

def hypo3(grid):
    """Hypothesis: 0 on anti-diagonal, 1 elsewhere"""
    result = []
    for r in range(len(grid)):
        new_row = []
        for c in range(len(grid[r])):
            if r + len(grid) - 1 == c:
                new_row.append(0)
            else:
                new_row.append(1)
        result.append(new_row)
    return result

def hypo4(grid):
    """Hypothesis: 0 where input>0, 1 elsewhere (input value determines fill)"""
    result = []
    for row in grid:
        new_row = []
        for val in row:
            if val != 0:
                new_row.append(0)
            else:
                new_row.append(1)
        result.append(new_row)
    return result

